{"word":"interferometer","translation":"interferômetro","definition_en":"A device that uses the interference of light, sound, or other waves to make precise measurements of wavelength, distance, or other properties.","definition_pt":"Um dispositivo que usa a interferência da luz, som ou outras ondas para fazer medições precisas de comprimento de onda, distância ou outras propriedades.","example_en":"The interferometer measured the distance to the star with incredible accuracy.","example_pt":"O interferômetro mediu a distância para a estrela com incrível precisão.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"interferon","translation":"interferon","definition_en":"A type of protein produced by cells in response to viral infection, which helps inhibit the replication of the virus and signals the immune system to fight the infection.","definition_pt":"Um tipo de proteína produzida pelas células em resposta à infecção viral, que ajuda a inibir a replicação do vírus e sinaliza o sistema imunológico para combater a infecção.","example_en":"Interferon is released by infected cells to warn neighboring cells of a viral threat.","example_pt":"Interferon é liberado por células infectadas para avisar as células vizinhas de uma ameaça viral.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"interjection","translation":"interjeição","definition_en":"A sudden, short utterance that expresses a strong emotion such as surprise, pain, joy, or anger.","definition_pt":"Uma expressão súbita e curta que expressa uma forte emoção, como surpresa, dor, alegria ou raiva.","example_en":"\"Ouch!\" is an interjection expressing pain.","example_pt":"\"Ai!\" é uma interjeição expressando dor.","cefr_level":"C1","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"interlace","translation":"entrançar","definition_en":"To join or connect things by twisting, weaving, or lacing them together.","definition_pt":"Juntar ou conectar as coisas, torcendo, tecendo, ou amarrando-as juntas.","example_en":"The artist interlaced the threads to create a beautiful pattern.","example_pt":"O artista entrelaçou os fios para criar um belo padrão.","cefr_level":"B2","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"interleave","translation":"intercalar","definition_en":"To intersperse the sectors on the concentric magnetic circular patterns written on a computer disk surface to guide the storing and recording of data.","definition_pt":"Intercalar os setores nos padrões circulares magnéticos concêntricos escritos em uma superfície de disco de computador para guiar o armazenamento e gravação de dados.","example_en":"The system interleaves the disk sectors to optimize read and write speeds.","example_pt":"O sistema interliga os setores de disco para otimizar as velocidades de leitura e gravação.","cefr_level":"C2","word_type":"verb","category_slug":"technology","frequency_rank":null},
{"word":"interlocutor","translation":"interlocutor","definition_en":"A person who takes part in a conversation or dialogue.","definition_pt":"Uma pessoa que participa de uma conversa ou diálogo.","example_en":"My interlocutor was a well-known professor of linguistics.","example_pt":"Meu interlocutor era um professor de linguística bem conhecido.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"intermediation","translation":"intermediação","definition_en":"The act of stepping in or mediating between parties to help them reach an agreement or settlement.","definition_pt":"O ato de intervir ou mediar entre as partes para ajudá-las a chegar a um acordo ou acordo.","example_en":"The neutral party's intermediation was crucial in ending the labor strike.","example_pt":"A intermediação do partido neutro foi crucial para acabar com a greve trabalhista.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"interment","translation":"enterro","definition_en":"The formal act of placing a dead body into a grave or tomb, often as part of a funeral ceremony.","definition_pt":"O ato formal de colocar um corpo morto em uma sepultura ou túmulo, muitas vezes como parte de uma cerimônia de funeral.","example_en":"The interment took place at the local cemetery.","example_pt":"O enterro aconteceu no cemitério local.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"intermezzo","translation":"intermezzo","definition_en":"A short, connecting movement placed between the main sections of a larger symphonic work.","definition_pt":"Um movimento curto e de ligação entre as seções principais de um trabalho sinfônico maior.","example_en":"The orchestra played a delicate intermezzo between the first and second movements.","example_pt":"A orquestra tocou um delicado intermezzo entre o primeiro e segundo movimentos.","cefr_level":"C1","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"intermittently","translation":"intermitentemente","definition_en":"In a way that stops and starts repeatedly over time, not continuously.","definition_pt":"De uma forma que pára e começa repetidamente ao longo do tempo, não continuamente.","example_en":"The rain fell intermittently throughout the day.","example_pt":"A chuva caiu intermitentemente durante todo o dia.","cefr_level":"B2","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"internalization","translation":"internalização","definition_en":"The process of absorbing and adopting external values, norms, or attitudes as one's own, making them part of one's internal belief system.","definition_pt":"O processo de absorver e adotar valores externos, normas ou atitudes como próprias, tornando-as parte do sistema de crenças internas.","example_en":"The internalization of ethical principles is crucial for moral development.","example_pt":"A internalização dos princípios éticos é crucial para o desenvolvimento moral.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"internationalism","translation":"internacionalismo","definition_en":"The principle or belief that nations should work together and prioritize shared interests over national differences.","definition_pt":"O princípio ou crença de que as nações devem trabalhar juntas e priorizar interesses compartilhados sobre as diferenças nacionais.","example_en":"Internationalism was a key theme of the post-war peace conference.","example_pt":"O internacionalismo foi um tema chave da conferência de paz pós-guerra.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"internationalization","translation":"internacionalização","definition_en":"The process of making something subject to the authority or influence of multiple nations.","definition_pt":"O processo de fazer algo sujeito à autoridade ou influência de várias nações.","example_en":"The internationalization of the river ensured free passage for all nations.","example_pt":"A internacionalização do rio garantiu passagem livre para todas as nações.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"internationalize","translation":"internacionalizar","definition_en":"To bring something under the authority or management of multiple nations.","definition_pt":"Para trazer algo sob a autoridade ou gestão de várias nações.","example_en":"The treaty sought to internationalize the disputed waterway.","example_pt":"O tratado tentou internacionalizar a água concorrida.","cefr_level":"C1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"interoperability","translation":"interoperabilidade","definition_en":"The ability of different computer systems, software, or networks to exchange and use information effectively, especially across a large, mixed network.","definition_pt":"A habilidade de diferentes sistemas de computador, software ou redes de trocar e usar informações de forma eficaz, especialmente em uma grande rede mista.","example_en":"The new software was designed with interoperability in mind, allowing it to work with older systems.","example_pt":"O novo software foi projetado com interoperabilidade em mente, permitindo que ele trabalhasse com sistemas mais antigos.","cefr_level":"C1","word_type":"noun","category_slug":"technology","frequency_rank":null},
{"word":"interpellate","translation":"interpelar","definition_en":"To formally question a government official, especially a minister, about a specific policy, action, or matter of public business in a parliamentary or legislative setting.","definition_pt":"Para questionar formalmente um funcionário do governo, especialmente um ministro, sobre uma política específica, ação ou assunto de negócios públicos em um ambiente parlamentar ou legislativo.","example_en":"The opposition party decided to interpellate the minister of finance regarding the new tax reforms.","example_pt":"O partido da oposição decidiu interpelar o ministro das finanças sobre as novas reformas fiscais.","cefr_level":"C2","word_type":"verb","category_slug":"politics","frequency_rank":null},
{"word":"interpolation","translation":"interpolação","definition_en":"A spoken or written message that is introduced or inserted into a conversation or text.","definition_pt":"Uma mensagem escrita ou falada que é introduzida ou inserida em uma conversa ou texto.","example_en":"The editor added an interpolation to clarify the author's point.","example_pt":"O editor acrescentou uma interpolação para esclarecer o ponto do autor.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"interpose","translation":"interpor","definition_en":"To place something between two other things or in the middle of something.","definition_pt":"Colocar algo entre outras duas coisas ou no meio de algo.","example_en":"The mediator interposed a new clause into the contract.","example_pt":"O mediador interpôs uma nova cláusula no contrato.","cefr_level":"C1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"interposition","translation":"interposição","definition_en":"The act of interjecting or interposing an action or remark that interrupts a process or conversation.","definition_pt":"O ato de interferir ou interpor uma ação ou observação que interrompe um processo ou conversa.","example_en":"His interposition during the debate caused a brief pause in the proceedings.","example_pt":"Sua interposição durante o debate causou uma breve pausa no processo.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"interpretable","translation":"interpretável","definition_en":"Able to be explained or understood in a particular way.","definition_pt":"Capaz de ser explicado ou compreendido de uma maneira particular.","example_en":"The data is interpretable by most researchers.","example_pt":"Os dados são interpretáveis pela maioria dos pesquisadores.","cefr_level":"B2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"interregnum","translation":"interregno","definition_en":"A period of time when a state, organization, or institution is without its usual leader or ruler, especially between the end of one reign and the beginning of the next.","definition_pt":"Um período em que um estado, organização ou instituição não tem seu líder ou governante habitual, especialmente entre o fim de um reinado e o começo do próximo.","example_en":"The country experienced a brief interregnum after the king's abdication.","example_pt":"O país passou por um breve interregno após a abdicação do rei.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"interrelation","translation":"inter-relação","definition_en":"A reciprocal relationship or connection between two or more things.","definition_pt":"Uma relação recíproca ou conexão entre duas ou mais coisas.","example_en":"The interrelation between diet and health is well documented.","example_pt":"A inter-relação entre dieta e saúde está bem documentada.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null}
]
$catalog$::jsonb) as v(
  word text,translation text,definition_en text,definition_pt text,example_en text,example_pt text,
